using System;

public struct Quote
{
    public string Id;
    public string Text;
    public string Author;
}

public static class FrenchQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elias_Canetti", Text = "Il n'est rien que l'homme redoute davantage que le contact de l'inconnu.", Author = "Elias Canetti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Monica_Bellucci", Text = "Peinture, musique, littérature, cinéma: seul le temps atteste de la valeur d'une œuvre. L'instant est toujours soumis aux aléas, aux émotions, à un certain état d'esprit. Pour pouvoir jauger, il faut attendre. Passer après le public, les critiques, les modes… Juger à nu. Poser un œil vierge.", Author = "Monica Bellucci" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anta_Babacar_Ngom", Text = "Nous sommes la troisième voie, la voix des sans voix, ceux qui n'ont jamais été en politique mais qui ont leur mot à dire.", Author = "Anta Babacar Ngom" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9sar_%28sculpteur%29", Text = "Je n’ai pas d’imagination. Elle ne me vient qu’avec le toucher et les yeux. Sans ces deux éléments, le cerveau ne fonctionne pas.", Author = "César (sculpteur)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Franc-ma%C3%A7onnerie", Text = "Le monde entier n'est qu'une grande république, dont chaque nation est une famille et chaque particulier un enfant.", Author = "Franc-maçonnerie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Albert_Schweitzer", Text = "La seule possibilité de donner un sens à son existence, c'est d'élever sa relation naturelle avec le monde à la hauteur d'une relation spirituelle.", Author = "Albert Schweitzer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Petit_Prince", Text = "Les grandes personnes ne comprennent jamais rien toutes seules, et c'est fatiguant, pour les enfants, de toujours et toujours leur donner des explications.", Author = "Le Petit Prince" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Katia_Lanero_Zamora", Text = "Règle n° 5: l'élégance est une manière d'être.", Author = "Katia Lanero Zamora" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Choses_vues", Text = "Les révolutions sont de magnifiques improvisatrices. Un peu échevelées quelquefois.", Author = "Choses vues" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Printemps_silencieux", Text = "À quelque étape qu'on empoisonne la chaîne alimentaire, on l'empoisonne partout.", Author = "Printemps silencieux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aholou_K%C3%A8k%C3%A8", Text = "L’avenir d’un être humain est entre les mains du créateur.", Author = "Aholou Kèkè" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Kropotkine", Text = "Qui dit État nécessairement dit guerre.", Author = "Pierre Kropotkine" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcel_Jouhandeau", Text = "Mais la notion de la vérité s'est tellement abaissée que si vous dites la vérité, on vous accuse de vouloir étonner ou scandaliser. Ce qui manque à l'esprit, c'est la hardiesse et la nuance, l'une excluant l'autre et l'une et l'autre sont nécessaires à l'appréhension et à l'expression de la vérité.", Author = "Marcel Jouhandeau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Gamarra", Text = "Je suis né le 10 juillet 1919 à Toulouse (Haute-Garonne). C'est une grande ville méridionale au carrefour de multiples influences: méditerranéennes et atlantiques.\nCe n'est point le midi azur et or, le midi carte postale comme celui de la Côte d'Azur, c'est un midi plus voilé, plus mouillé.", Author = "Pierre Gamarra" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Annette_Wieviorka", Text = "Les historiens sont ceux qui ont été les gardiens de l'histoire et de l'humanité.", Author = "Annette Wieviorka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andr%C3%A9_Voisin", Text = "De l'équilibre du sol, dépend l'équilibre de la plante, de l'animal et de l'homme.", Author = "André Voisin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Belle_%C3%A9poque", Text = "Grand pays de bronze de la belle époque, par tes chemins en pente douce, l'inquiétude a déserté.", Author = "Belle époque" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatouma_Amadou_Djibril", Text = "Je suis en contact avec les résistants et il leur manque parfois les moyens pour faire face à cette Armée inconsciente.", Author = "Fatouma Amadou Djibril" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bonheur", Text = "Un grand obstacle au bonheur, c'est de s'attendre à un trop grand bonheur.", Author = "Bonheur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_Abbott_McNeill_Whistler", Text = "Chez le peintre Whistler, les nocturnes sont visités par les étoiles. Même les fenêtres sont des astres.", Author = "James Abbott McNeill Whistler" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wassyl_Slipak", Text = "L'Ukraine peut réussir et faire entendre sa voix sur la scène internationale à condition qu'elle écoute la voix de son peuple.", Author = "Wassyl Slipak" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ernestine_Nyoka", Text = "Le pouvoir public a l’obligation de favoriser les femmes à occuper de postes aux niveaux central, national et local.", Author = "Ernestine Nyoka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Francis_Parkman", Text = "La civilisation espagnole a écrasé l’Indien; la civilisation anglaise l’a méprisé et négligé; la civilisation française l’a étreint et chéri.", Author = "Francis Parkman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89mile_Faguet", Text = "Deux états sociaux ruinent l'idée ou plutôt le sentiment de la patrie: la vie politique trop violente, et la vie politique nulle.", Author = "Émile Faguet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Curnonsky", Text = "L'Ardèche est le paradis des gourmets.", Author = "Curnonsky" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_Robert", Text = "Aujourd’hui, certains ont une vision purement intellectuelle de l’homme antique; à l’opposé d’autres ne se livrent plus qu’à l’archéologie du tesson. Pour moi, il faut être toujours plus attentif aux multiples rapports entre l’homme, ses mots, les choses et la nature. La terre et le papier.", Author = "Louis Robert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Robots_et_l%27Empire", Text = "Ce n'est pas ce qu'on est qui compte, mais ce que l'on pense être.", Author = "Les Robots et l'Empire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Orokiatou_Baro", Text = "L'éducation est un gage d'émancipation de l’humain. Elle est comme le toit d'une hutte. Quelque admirable que soit la bâtisse, sans toiture, elle est exposée à toutes sortes d'intempéries. L'éducation scolaire et sociétale élève l'homme", Author = "Orokiatou Baro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ndeye_Binta_Leye", Text = "C'était très difficile. Je recevais moi-même les clients et je m'occupais de la broderie anglaise. Je devais m'occuper en même temps des tailleurs, de la facturation et des livraisons. Il y avait aussi mon foyer à gérer, avec un enfant surtout. Mais je croyais au succès.", Author = "Ndeye Binta Leye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/G%C3%A9rald_de_Palmas", Text = "J'ai passé tellement de temps\nA faire mon intéressant\nQu'un soir je me suis perdu\nVoilà ce que je vais faire:\nAller au bout de la Terre\nL'océan à perte de vue", Author = "Gérald de Palmas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fictions", Text = "C’est à la conjonction d’un miroir et d’une encyclopédie que je dois la découverte d’Uqbar.", Author = "Fictions" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Paul_Pauly", Text = "Défendre la jeunesse, c'est mettre à sa portée tous les moyens de faire valoir ses aptitudes et ses goûts.", Author = "Paul Pauly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ismail_Kadare", Text = "La vraie littérature a son propre calendrier, sa propre liberté qui n'a rien à voir avec la liberté extérieure.", Author = "Ismail Kadare" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nourane_Fotsing_Moluh_Hassana", Text = "Pour toute personne qui veut faire des affaires, intéressez vous aux réseaux sociaux. C'est vraiment un très bel élément pour pouvoir décoller. Il faudrait que la jeunesse comprenne vraiment ça. C'est très très important.", Author = "Nourane Fotsing Moluh Hassana" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9v%C3%A9rien_Rurangwa", Text = "Ils m’ont tué, moi et toute ma famille, sur une colline du Rwanda, en avril 1994, mais je ne suis pas mort.", Author = "Révérien Rurangwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Voix_des_grands_chefs_indiens", Text = "Un homme fort rencontre toujours un homme plus fort que lui.", Author = "Voix des grands chefs indiens" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nicole_Croisille", Text = "La vie devient de plus en plus difficile. Survivre, ça n'est pas suffisant, il faut aussi vivre et je crois que la chose la plus gratuite qu'on puisse s'offrir les uns les autres, c'est infiniment l'amour.", Author = "Nicole Croisille" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Muhammad_Sa%C3%AFd_al-Ashmawi", Text = "Dieu voulait que l'islam fût une religion, mais les hommes ont voulu en faire une politique.", Author = "Muhammad Saïd al-Ashmawi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Corbeau_%28film%2C_1943%29", Text = "Docteur Michel Vorzet: Je ne connais rien de plus ridicule qu’un congrès de médecins, si ce n’est un congrès de psychiatres.", Author = "Le Corbeau (film, 1943)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Loreena_McKennitt", Text = "Je discerne les lumières dans le lointain\nTremblantes dans le sombre manteau de la nuit\nLes bougies et les lanternes dansent, dansent\nUne valse pendant la Nuit de la Fête des Morts", Author = "Loreena McKennitt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Corine_Pelluchon", Text = "Peu de personnes ont compris que le défi soulevé par une économie décarbonée, était de transformer certains renoncements en perspectives de bonheur.", Author = "Corine Pelluchon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Katharine_Hepburn", Text = "Je n'ai aucune crainte de la mort. Ce doit être merveilleux, comme un long sommeil. Et puis, regardons les choses en face: ce qui compte c'est ce qu'on fait de sa vie.", Author = "Katharine Hepburn" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Louis_Guez_de_Balzac", Text = "L'utilité publique se fait souvent du dommage des particuliers.", Author = "Jean-Louis Guez de Balzac" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ir%C3%A8ne_Esambo_Diata", Text = "La femme est le socle de la famille et de la nation.", Author = "Irène Esambo Diata" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacques_Villegl%C3%A9", Text = "L'art n'a pas à imiter le monde mais à le révéler.", Author = "Jacques Villeglé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Langue", Text = "Une langue est un dialecte avec une armée et une flotte.", Author = "Langue" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alain_Jouffroy", Text = "Écrire un poème, c'est se tirer une balle dans les mots.", Author = "Alain Jouffroy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Souleymane_Ciss%C3%A9", Text = "Ma façon de vivre, c’est de croire en l’avenir; si j’étais fataliste, je ne serais pas cinéaste. Rien ne me poussait à faire du cinéma. C’est moi qui l’ai choisi. Je voulais voir les choses et les faire voir. Quand on a cette curiosité, on ne peut pas être fataliste.", Author = "Souleymane Cissé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatoumata_K%C3%A9b%C3%A9", Text = "Pour mes parents, les études ça ne veut rien dire. Pour eux, le but c’est d’avoir un travail qui permet de payer ses factures et de vivre de manière correcte. Quand je leur ai parlé d’astronomie, ils n’ont pas pensé à la difficulté, ils m’ont dit: ça sert à quoi?", Author = "Fatoumata Kébé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sahadi_Sandi_Abdou", Text = "Les calamités naturelles, plus précisément les inondations, nous rappellent l’urgence de mettre en œuvre l’accord de Paris sur le changement climatique.", Author = "Sahadi Sandi Abdou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Pierre_Changeux", Text = "Les sciences du système nerveux sont devenues moléculaires.", Author = "Jean-Pierre Changeux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Olivia_Yac%C3%A9", Text = "<<Notre présence compte, et nos voix doivent être entendues.>>", Author = "Olivia Yacé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Frot", Text = "Je suis consciente que dans mon travail j'ai envie que les choses soient vues et entendues", Author = "Catherine Frot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Odile_Tobner", Text = "C'est une chance d'être obligé de faire ce qu'on aime, et d'en vivre!", Author = "Odile Tobner" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yacine_Diop", Text = "Ma grand mère, Aissatou Konaté, a joué au basket et mon grand père Youssouf Dieng était capitaine de l’équipe nationale de Guinée.", Author = "Yacine Diop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andr%C3%A9_Gorz", Text = "Nous pouvons vivre mieux en produisant moins.", Author = "André Gorz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/James_A._Michener", Text = "Les chercheurs rêvent d’accomplir de grandes choses, les ingénieurs les réalisent.", Author = "James A. Michener" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Karelle_Vignon-Vullierme", Text = "Je ne suis même pas une professionnelle du domaine! J’ai appris à cuisiner sur Internet, dans les livres et grâce à des émissions télévisées.", Author = "Karelle Vignon-Vullierme" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gilles_Perret", Text = "Je suis ouvert au débat. Mais je ne veux être jugé que par des gens qui ont vu mes films.", Author = "Gilles Perret" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9line_Orgelle_Kentsop", Text = "Ceux qui ne me connaissent pas disent que la femme-là doit être naturellement méchante en dehors du film. Mais ceux qui me connaissent savent que je joue bien mes rôles.", Author = "Céline Orgelle Kentsop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Matilda_McCrear", Text = "Son histoire me donne des émotions mitigées parce que si elle n’avait pas été amenée ici, je n'y serais pas. Mais c’est difficile de lire sur ce qu’elle a vécu.", Author = "Matilda McCrear" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ma%C3%AFmouna_Dieye", Text = "On vous a vendu ce projet, vous l'avez payé, vous l'avez acheté au prix fort parce que vous y croyez.", Author = "Maïmouna Dieye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chantal_Safu", Text = "La parité n'est pas une donne facile, mais une conquête.", Author = "Chantal Safu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/F%C3%A9lix_Timmermans", Text = "Le soleil avait plongé, pareil à un poisson d’or.", Author = "Félix Timmermans" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christine_Arnothy", Text = "La moralité est faite pour les pauvres, pour mieux les tenir.", Author = "Christine Arnothy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kadidiatou_Gazibo", Text = "Dans cette configuration, l’État perd son monopole de ‘faiseur’ de paix et devient un acteur parmi tant d’autres", Author = "Kadidiatou Gazibo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georges_Braque", Text = "En art le progrès ne consiste pas dans l’extension mais dans la connaissance de ses limites.", Author = "Georges Braque" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pascal_N%27Kou%C3%A9", Text = "Ce ne sont pas nos danses qui nous aident à prier, elles s’arrêtent au corps alors que pour prier, il faut aller jusqu’au cœur.", Author = "Pascal N'Koué" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nkosazana_Dlamini-Zuma", Text = "La renaissance africaine est un processus et non un événement. Il fallait commencer par la libération, car un peuple opprimé ne peut pas renaître. Maintenant, la libération doit avoir lieu du point de vue du développement, du développement durable et de la modernisation.", Author = "Nkosazana Dlamini-Zuma" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Olive_Lembe_di_Sita", Text = "C’est dans la cohésion que nous saurons vaincre les ennemis qui nous envient, pour protéger notre si beau pays.", Author = "Olive Lembe di Sita" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stephen_Sondheim", Text = "Je suis un auteur paresseux. Mon idée du paradis ne consiste pas à écrire. D'un autre côté, c'est évident que j'écris de manière compulsive.", Author = "Stephen Sondheim" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alix_de_Saint-Andr%C3%A9", Text = "Les anges volent sans œillères d’une religion à l’autre.", Author = "Alix de Saint-André" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gasandji_R%C3%AAver", Text = "Je tuerai, je tuerai, je tuerai le temps...", Author = "Gasandji Rêver" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Moulin_rouge_%21", Text = "La seule vérité découverte à ce jour c'est qu'il suffit d'aimer et de l'être en retour.", Author = "Moulin rouge !" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Joseph_Joubert", Text = "Quand mes amis sont borgnes, je les regarde de profil.", Author = "Joseph Joubert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Jacques_Semp%C3%A9", Text = "Ce que tu cherches est déjà en toi, mais tu l'as oublié et ça te rend fragile et incertain.", Author = "Jean-Jacques Sempé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniella_Okeke", Text = "Mon conseil aux femmes nigérianes est de ne pas sacrifier leur dignité pour réussir dans la vie.", Author = "Daniella Okeke" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mohandas_Karamchand_Gandhi", Text = "Je tiens au progrès, je tiens à la détermination personnelle, à la liberté, mais je les veux pour l'âme. Je doute que l'âge de l'acier soit supérieur à l'âge de pierre. Peu m'importe. C'est à l'évolution de l'âme qu'il faut consacrer toute notre intelligence et toutes nos autres facultés.", Author = "Mohandas Karamchand Gandhi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/M%C3%A8re_Teresa", Text = "Hier n'est plus, demain n'est pas encore. Nous n'avons qu'aujourd'hui. Commençons.", Author = "Mère Teresa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zerocalcare", Text = "L'identité c'est ce qui n'est qu'à toi.\nEt la seule chose qui n'appartient qu'à toi, ce sont tes secrets.\n\nUn homme sans aucun secret est un homme sans identité.", Author = "Zerocalcare" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Passions_schismatiques", Text = "Ce sont nos défauts qui nous poussent dans la société, et nos qualités qui nous perdent.", Author = "Les Passions schismatiques" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/George_Eliot", Text = "Examinez bien vos paroles, et vous trouverez que, lors même que vous n'avez aucune motif d'être faux, il est très difficile de dire l'exacte vérité.", Author = "George Eliot" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Conseil_f%C3%A9d%C3%A9ral", Text = "Notre planète se rapproche des limites de ce qu’elle peut supporter. Les changements climatiques, la consommation excessive de ressources et la perte de biodiversité constituent des risques menaçant les fondements de notre vie.", Author = "Conseil fédéral" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dora_Decca", Text = "Les enfants de la rue, quand ils trouvent une mère, c’est une vraie mère.", Author = "Dora Decca" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roger_Caillois", Text = "Roger Caillois était un écrivain français de premier rang […] \nEt il pensait si fort et si vite qu'il lui arrivait de bégayer.", Author = "Roger Caillois" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kemi_Adetiba", Text = "Je pense que, pour moi, l'une des choses les plus importantes, c'est que je ne souhaite tromper personne.", Author = "Kemi Adetiba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Camara_Nangala", Text = "Il suffit d’un brin de volonté et d’effort pour renverser la vapeur.", Author = "Camara Nangala" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mouvement_de_lib%C3%A9ration_des_femmes", Text = "Reconnaissons-nous, les femmes,\nParlons-nous, regardons-nous,\nEnsemble on nous opprime, les femmes,\nEnsemble révoltons-nous.\n\nLevons-nous, femmes esclaves,\nEt brisons nos entraves,\nDebout! Debout!", Author = "Mouvement de libération des femmes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Esperan%C3%A7a_da_Costa", Text = "Les Angolaises sont en mesure de déployer leurs ailes grâce aux investissements considérables du gouvernement dans l'éducation des femmes, le développement équilibré, l'égalité des sexes et l'autonomisation.", Author = "Esperança da Costa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sanzy_Viany", Text = "Chaque jour pour moi est un jour nouveau pour pouvoir me faire connaître par un Camerounais de plus.", Author = "Sanzy Viany" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Affaire_Dutroux", Text = "Mais malgré ce climat de pression exceptionnelle, les dossiers n'ont jamais abouti.", Author = "Affaire Dutroux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Gautier", Text = "On avait revu sur les autoroutes des citoyens honorables prêts à tout pour fuir. Les plus anciens avaient des réminiscences de juin 1940, les moins vieux d'Alger en juillet 1962. C'était toujours le même peuple qui fuyait.", Author = "Philippe Gautier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeff_Sutton", Text = "Nous définissons ce que nous percevons, rien de plus.", Author = "Jeff Sutton" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Ehi", Text = "Ne tente pas de te conformer à l'histoire de quelqu'un d'autre, car tu risquerais de priver le monde de la belle histoire que tu aurais pu être.", Author = "Ada Ehi" },
